begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(15);
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','coach-lifecycle@example.com') on conflict do nothing;
insert into public.profiles(id,username,timezone) values('11111111-1111-4111-8111-111111111111','coach_lifecycle','UTC') on conflict(id) do nothing;
create temporary table home as select public.ensure_coach_home('11111111-1111-4111-8111-111111111111') id;
create temporary table accepted as select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'22222222-2222-4222-8222-222222222222','How is today going?','{}',0,'first') result;
select is((select result->>'created' from accepted),'true','first send is accepted');
select is(public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'22222222-2222-4222-8222-222222222222','How is today going?','{}',0,'first')->>'created','false','reconnect replays the accepted identity');
select is((select count(*)::integer from public.coach_messages where thread_id=(select id from home)),1,'replay does not append another human message');
select throws_ok($$select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'22222222-2222-4222-8222-222222222222','Changed content','{}',0,'changed')$$,'P0001','idempotency_conflict','reused identities reject changed payloads');
select throws_ok($$select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'33333333-3333-4333-8333-333333333333','Next question','{}',1,'next')$$,'P0001','thread_busy','another request cannot run concurrently');
select public.finish_coach_run('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','Here is your current progress','{}');
select is((select status from public.coach_runs where id='22222222-2222-4222-8222-222222222222'),'completed','the answer and completed run persist together');
select is((select version from public.coach_threads where id=(select id from home)),2,'the reply advances the durable conversation version');
select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'33333333-3333-4333-8333-333333333333','Next question','{}',2,'next');
update public.coach_runs set status='failed' where id='33333333-3333-4333-8333-333333333333';
select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'44444444-4444-4444-8444-444444444444','Next question','{}',3,'retry','33333333-3333-4333-8333-333333333333');
select is((select user_message_id from public.coach_runs where id='44444444-4444-4444-8444-444444444444'),(select user_message_id from public.coach_runs where id='33333333-3333-4333-8333-333333333333'),'explicit retry reuses the saved human message');
select is((select count(*)::integer from public.coach_messages where thread_id=(select id from home)),3,'retry adds no duplicate human transcript');
select throws_ok($$select public.begin_coach_run('99999999-9999-4999-8999-999999999999',(select id from home),gen_random_uuid(),'Hello','{}',3,'foreign')$$,'P0001','thread_not_found','a service caller must still bind the thread owner');
select is((select version from public.coach_topics where is_default and owner_id='11111111-1111-4111-8111-111111111111'),3,'each accepted turn fences older topic summaries');
update public.coach_runs set status='cancelled' where id='44444444-4444-4444-8444-444444444444';
select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'55555555-5555-4555-8555-555555555555','Newer question','{}',3,'newer');
update public.coach_runs set status='cancelled' where id='55555555-5555-4555-8555-555555555555';
select throws_ok($$select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),gen_random_uuid(),'Next question','{}',4,'old-retry','33333333-3333-4333-8333-333333333333')$$,'P0001','retry_unavailable','an older failed question cannot be appended after a newer turn');
select public.begin_coach_run('11111111-1111-4111-8111-111111111111',(select id from home),'66666666-6666-4666-8666-666666666666','Newer question','{}',4,'latest-retry','55555555-5555-4555-8555-555555555555');
select public.manage_coach_entity('11111111-1111-4111-8111-111111111111','thread',(select id from home),4,'{"archived":true}');
select throws_ok($$select public.finish_coach_run('11111111-1111-4111-8111-111111111111','66666666-6666-4666-8666-666666666666','Late answer','{}')$$,'P0001','topic_archived','archiving prevents late answers and actions');
select throws_ok($$select public.manage_coach_entity('11111111-1111-4111-8111-111111111111','thread',(select id from home),4,'{"title":"Stale"}')$$,'P0001','conversation_conflict','management checks the version atomically');
select throws_ok($$select public.manage_coach_entity('11111111-1111-4111-8111-111111111111','topic',(select topic_id from public.coach_threads where id=(select id from home)),(select version from public.coach_topics where is_default and owner_id='11111111-1111-4111-8111-111111111111'),' {"archived":true}')$$,'P0001','default_topic','the default topic is protected at the write boundary');
select * from finish();rollback;
